from fastapi import FastAPI, Query
from fastapi.testclient import TestClient
from pydantic import Field

app = FastAPI()

@app.get("/test")
def test_endpoint(q: str = Query(validation_alias="val_alias")):
    return {"q": q}

client = TestClient(app)

def test_validation_alias():
    response = client.get("/test", params={"val_alias": "hello"})
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"q": "hello"}

def test_alias():
    # This should also work if alias is used instead of validation_alias
    @app.get("/test_alias")
    def test_alias_endpoint(q: str = Query(alias="alias_alias")):
        return {"q": q}

    response = client.get("/test_alias", params={"alias_alias": "world"})
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"q": "world"}

if __name__ == "__main__":
    try:
        test_validation_alias()
        print("test_validation_alias passed")
        test_alias()
        print("test_alias passed")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
